DECLARE @execution_id BIGINT;

EXEC [SSISDB].[catalog].[create_execution]
  @package_name = N'LoadSales.dtsx',
  @execution_id = @execution_id OUTPUT,
  @folder_name = N'ETL',
  @project_name = N'SalesIntegration',
  @use32bitruntime = FALSE;

-- Set a package parameter for the source folder path
EXEC [SSISDB].[catalog].[set_execution_parameter_value]
  @execution_id = @execution_id,
  @object_type = 50,
  @parameter_name = N'LOGFOLDER',
  @parameter_value = N'\\fileserver\etl\logs';

-- Start the package execution
EXEC [SSISDB].[catalog].[start_execution]
  @execution_id = @execution_id;

-- Monitor the running execution
SELECT @execution_id AS ExecutionID,
  status, start_time, end_time
FROM [SSISDB].[catalog].[executions]
WHERE execution_id = @execution_id;
